import java.util.*;
import java.io.*;

public class Main {
    static int n, m, P;
    static long[][] dwu;
    static long[] dp1;
    static long[][] dp2;
    static long[][] dp3;
    static long[] cnt;

    static void self_mult(long[] a, int b) {
        for (int i = 0; i < a.length; i++) {
            a[i] = (a[i] * b) % P;
        }
    }

    static long multiply(long a, long b) {
        return (a * b) % P;
    }

    static void add_modulo(long[] a, long b) {
        for (int i = 0; i < a.length; i++) {
            a[i] += b;
            if (a[i] >= P) a[i] -= P;
        }
    }

    static void add_modulo(long a, long b, long[] result) {
        result[0] = a + b;
        if (result[0] >= P) result[0] -= P;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        P = Integer.parseInt(st.nextToken());

        dwu = new long[n + 2][n + 2];
        for (int i = 0; i <= n + 1; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == 0) {
                    dwu[i][j] = 1;
                } else {
                    dwu[i][j] = dwu[i - 1][j];
                    dwu[i][j] = (dwu[i][j] + dwu[i - 1][j - 1]) % P;
                }
            }
        }

        dp1 = new long[m + 1];
        cnt = new long[m + 1];
        for (int i = 0; i <= m; i++) {
            dp1[i] = 0;
            cnt[i] = 0;
        }
        cnt[0] = 1;

        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                long val = 0;
                val = (val + multiply(dp1[j], cnt[i - j - 1])) % P;
                val = (val + multiply(dp1[i - j - 1], cnt[j])) % P;
                val = (val * (j + 1)) % P;

                long temp = dwu[i - 1][j];
                temp = (temp * cnt[j]) % P;
                temp = (temp * cnt[i - j - 1]) % P;
                temp = (temp * (j + 1)) % P;
                cnt[i] = (cnt[i] + temp) % P;

                dp1[i] = (dp1[i] + val) % P;
            }
            cnt[i] = (cnt[i] + cnt[i]) % P;
            dp1[i] = (dp1[i] + dp1[i]) % P;
        }

        int sizeN = n + 2;
        int sizeM = m + 2;
        dp2 = new long[sizeN][sizeM];
        dp3 = new long[sizeN][sizeM];

        for (int i = 0; i < sizeN; i++) {
            Arrays.fill(dp2[i], 0);
            Arrays.fill(dp3[i], 0);
        }

        dp2[0][0] = 1;

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k <= m; k++) {
                    if (j + k <= m && i + k + 1 <= n + 1) {
                        long val = dp2[i][j];
                        val = (val * dwu[m - j][k]) % P;
                        val = (val * cnt[k]) % P;

                        long val3 = dp3[i][j];
                        val3 = (val3 * cnt[k]) % P;
                        val3 = (val3 + multiply(dp1[k], dp2[i][j])) % P;
                        val3 = (val3 * dwu[m - j][k]) % P;

                        int ni = i + k + 1;
                        int nj = j + k;
                        dp3[ni][nj] = (dp3[ni][nj] + val3) % P;
                        dp2[ni][nj] = (dp2[ni][nj] + val) % P;
                    }
                }
            }
        }

        System.out.println(dp3[n + 1][m]);
    }
}
